def solve(x):
    try:
        result = tokzonlib.wrap(x)
        if result is not None:
            return result
        else:
            result = tokzonlib.retry(x)
            if result is not None:
                return result
            else:
            return None
    except (tokzonlib.TokZoneError, tokzonlib.TimeoutException):
        return None
    return None

